import csv
from datetime import datetime
from zoneinfo import ZoneInfo

la=ZoneInfo('America/Los_Angeles')

rows=[]
with open('/app/readings.csv',newline='') as f:
    r=csv.DictReader(f)
    for row in r:
        ts=datetime.fromisoformat(row['ts']).replace(tzinfo=ZoneInfo('UTC'))
        reg=float(row['register_kwh'])
        local=ts.astimezone(la)
        rows.append((ts,local,reg))
rows.sort(key=lambda x:x[0])

start=datetime(2026,11,1,0,0,0,tzinfo=la)
end=datetime(2026,12,1,0,0,0,tzinfo=la)

start_reg=end_reg=None
flags=[]
for ts,local,reg in rows:
    if local==start:
        start_reg=reg
    if local==end:
        end_reg=reg

if start_reg is None:
    # last before start
    before=[(l,r) for _,l,r in rows if l<start]
    if before:
        l,r=before[-1]
        start_reg=r
        flags.append('missing_exact_start_boundary')
    else:
        flags.append('no_data_before_start')

if end_reg is None:
    before=[(l,r) for _,l,r in rows if l<end]
    if before:
        l,r=before[-1]
        end_reg=r
        flags.append('missing_exact_end_boundary')
    else:
        flags.append('no_data_before_end')

# check continuity within month
prev_reg=None
prev_local=None
neg_count=0
max_gap_hours=0
in_month=[]
for ts,local,reg in rows:
    if start<=local<end:
        in_month.append((local,reg))
        if prev_reg is not None:
            diff=reg-prev_reg
            if diff<0:
                neg_count+=1
        prev_reg=reg
        prev_local=local

# check gaps: expect hourly local timestamps; handle DST fall back creates duplicate hour.
# We'll check UTC spacing instead among in-month rows.
prev_ts=None
for ts,local,reg in rows:
    if start<=local<end:
        if prev_ts is not None:
            gap=(ts-prev_ts).total_seconds()/3600
            if gap>max_gap_hours:
                max_gap_hours=gap
        prev_ts=ts

if neg_count:
    flags.append(f'negative_diffs:{neg_count}')
if max_gap_hours>1.1:
    flags.append(f'gaps_max_hours:{max_gap_hours:.1f}')

if start_reg is None or end_reg is None:
    import json
    out={'status':'cannot_determine','reason':'insufficient boundary data','flags':flags}
else:
    cons=end_reg-start_reg
    out={'answer':cons,'flags':flags}

